/* Target mobile devices (adjust 768px to your mobile breakpoint if needed) */
@media screen and (max-width: 768px) {
  #zsiq_float {
    /* 
      Set 'bottom' to the height of your fixed bar PLUS any extra gap/padding you want.
      Example: If your bottom bar is 60px high, set this to 70px or 80px.
    */
    bottom: 100px !important;
    left:85%!important;

    /* Ensures the chat widget floats above other elements if overlapped */
    z-index: 99999 !important;
  }
}

