[{"id":"299","elType":"widget","settings":{"tabs":[{"tab_title":"What specific areas does Clear Day Bath Solutions cover for remodeling projects?","tab_content":"<p><span class="" data-path-to-node="2,0,0,2"><span class="citation-564">We are proud to be a premier local provider of custom bathroom solutions throughout the entire Northern Virginia and Central Maryland regions</span></span><span class="" data-path-to-node="2,0,0,4">. </span><span class="" data-path-to-node="2,0,0,6"><span class="citation-563">Our core service areas include </span><b data-path-to-node="2,0,0,6" data-index-in-node="31"><span class="citation-563">Woodbridge, Alexandria, and Manassas</span></b><span class="citation-563"> in Virginia, as well as </span><b data-path-to-node="2,0,0,6" data-index-in-node="92"><span class="citation-563">Frederick, Columbia, and Annapolis</span></b><span class="citation-563"> in Maryland</span></span><span class="" data-path-to-node="2,0,0,8">. </span><span class="" data-path-to-node="2,0,0,10"><span class="citation-562">We also extend our expert remodeling services to homeowners in Stafford, Warrenton, Hagerstown, Waldorf, and across the Greater DC Metro area to ensure quality craftsmanship is accessible to our neighbors</span></span><span class="" data-path-to-node="2,0,0,12">.</span></p>","_id":"85c7583"},{"tab_title":"How does a tub-to-shower conversion benefit my home’s value and safety?","tab_content":"<p><span data-path-to-node="2,1,0,2"><span class="citation-561">A professional tub-to-shower conversion is one of the most effective ways to modernize an outdated bathroom while significantly increasing daily accessibility</span></span><span data-path-to-node="2,1,0,4">. </span><span data-path-to-node="2,1,0,6"><span class="citation-560">By replacing a high-sided tub with a sleek, low-threshold walk-in shower, you create a safer environment that reduces trip hazards—an essential feature for aging-in-place or multi-generational households</span></span><span data-path-to-node="2,1,0,8">. Beyond safety, these conversions offer a contemporary aesthetic that appeals to modern buyers, making it a high-return investment for your property.</span></p>","_id":"d7613d9"},{"tab_title":"What exactly is included in your custom wet-area remodeling services?","tab_content":"<p><span data-path-to-node="2,2,0,2"><span class="citation-559">Our custom wet-area remodeling focuses specifically on the most utilized parts of your bathroom: the shower and tub space</span></span><span data-path-to-node="2,2,0,4">. </span><span data-path-to-node="2,2,0,6"><span class="citation-558">Unlike a full-scale demolition that can take weeks, we specialize in high-impact transformations such as installing premium wall surrounds, upgrading fixtures, and implementing safety showers with built-in seating and grab bars</span></span><span data-path-to-node="2,2,0,8">. </span><span data-path-to-node="2,2,0,10"><span class="citation-557">Every project is tailored to your specific vision, ensuring the final result is a "clear" reflection of your style and functional needs</span></span><span data-path-to-node="2,2,0,12">.</span></p>","_id":"ba7104c"},{"tab_title":"What are your hours of operation, and how can I schedule a consultation?","tab_content":"<p><span data-path-to-node="2,3,0,2"><span class="citation-556">We understand that our customers have busy lives, which is why Clear Day Bath Solutions offers extended business hours to fit your schedule</span></span><span data-path-to-node="2,3,0,4">. </span><span data-path-to-node="2,3,0,6"><span class="citation-555">We are available for consultations and project discussions </span><b data-path-to-node="2,3,0,6" data-index-in-node="59"><span class="citation-555">Monday through Friday from 8 am to 8 pm</span></b><span class="citation-555">, and on </span><b data-path-to-node="2,3,0,6" data-index-in-node="107"><span class="citation-555">Saturdays and Sundays from 9 am to 4 pm</span></b></span><span data-path-to-node="2,3,0,8">. </span><span data-path-to-node="2,3,0,10"><span class="citation-554">You can reach out to our primary contact, Griffin Spencer, via phone at </span><b data-path-to-node="2,3,0,10" data-index-in-node="72"><span class="citation-554">804-840-0467</span></b><span class="citation-554"> to start your project</span></span><span data-path-to-node="2,3,0,12">.</span></p>","_id":"33381fc"},{"tab_title":"What makes Clear Day Bath Solutions different from larger bath franchises?","tab_content":"<p><span data-path-to-node="2,4,0,2"><span class="citation-553 interactive-span-hovered">As a locally owned business established in </span><b data-path-to-node="2,4,0,2" data-index-in-node="43"><span class="citation-553 interactive-span-hovered">January 2026</span></b><span class="citation-553 interactive-span-hovered">, we provide a level of personalized attention and transparency that national "big box" franchises often lack</span></span><span data-path-to-node="2,4,0,4">. </span><span data-path-to-node="2,4,0,6"><span class="citation-552">We don't believe in high-pressure sales; instead, we focus on a collaborative approach, utilizing modern communication to keep you updated from the first quote to the final walkthrough</span></span><span data-path-to-node="2,4,0,8">. </span><span data-path-to-node="2,4,0,10"><span class="citation-551">Our "Clear Day" philosophy means no hidden fees, realistic timelines, and a dedicated commitment to outstanding local craftsmanship in every home we enter</span></span><span data-path-to-node="2,4,0,12">.</span></p>","_id":"56d984d"}],"selected_icon":{"value":"fas fa-plus","library":"fa-solid"},"selected_active_icon":{"value":"fas fa-minus","library":"fa-solid"},"faq_schema":"yes","border_width":{"unit":"px","size":0,"sizes":[]},"space_between":{"unit":"px","size":22,"sizes":[]},"title_typography_typography":"custom","title_typography_font_family":"Poppins","title_typography_font_size":{"unit":"px","size":18,"sizes":[]},"title_typography_font_weight":"600","icon_align":"right","icon_color":"#8D8D8D","icon_active_color":"#8D8D8D","content_typography_typography":"custom","content_typography_font_family":"Montserrat","content_padding":{"unit":"%","top":"3","right":"3","bottom":"3","left":"3","isLinked":true},"content_padding_tablet":{"unit":"%","top":"","right":"","bottom":"","left":"","isLinked":true},"content_padding_mobile":{"unit":"%","top":"","right":"","bottom":"","left":"","isLinked":true},"pa_condition_repeater":[],"premium_tooltip_text":"Hi, I'm a global tooltip.","premium_tooltip_position":"top,bottom","pa_cursor_ftext":"Premium Follow Text","pa_badge_text":"New","premium_mscroll_repeater":[],"custom_css":" .elementor-toggle-item{
